<?php require 'config.php'; fechar_offlines(); $alertas=gerar_alertas_inteligentes(); header_page('Painel');
$funs=jread('funcionarios',[]); $disp=jread('dispositivos',[]); $pres=jread('presencas',[]); $conf=jread('config',[]); $scan=jread('scan_status',[]); $tol=(int)($conf['tolerancia_offline_min']??15); $hoje=date('Y-m-d');
$online=0; $almoco=0; $ausentes=0; $extraHoje=0; $minHoje=0; foreach($funs as $f){ $dev=dispositivo_do_funcionario($f['id']); $p=$pres[$hoje.'_'.$f['id']]??null; $isOn=$dev && !empty($dev['ultimo_visto']) && time()-strtotime($dev['ultimo_visto']) <= $tol*60; if($isOn) $online++; else $ausentes++; if(($p['status']??'')==='almoco') $almoco++; $extraHoje+=(int)($p['extra_minutos']??0); $minHoje+=(int)($p['minutos']??0); }
$leitorOk=!empty($scan['ultimo_scan']) && time()-strtotime($scan['ultimo_scan'])<180;
?>
<section class="hero"><div><h2>Dashboard operacional</h2><p>Controle em tempo real de presença, almoço, horas e alertas inteligentes.</p></div><span class="pill <?=$leitorOk?'ok':'off'?>">Leitor <?=$leitorOk?'ativo':'parado'?></span></section>
<section class="grid kpis"><div class="card"><p>Trabalhando agora</p><div class="big ok"><?=$online?></div></div><div class="card"><p>Em almoço/pausa</p><div class="big warn"><?=$almoco?></div></div><div class="card"><p>Ausentes/offline</p><div class="big off"><?=$ausentes?></div></div><div class="card"><p>Horas extras hoje</p><div class="big"><?=hhmm_from_min($extraHoje)?></div></div><div class="card"><p>Total trabalhado hoje</p><div class="big"><?=hhmm_from_min($minHoje)?></div></div><div class="card"><p>Última leitura</p><div class="big smallbig"><?=!empty($scan['ultimo_scan'])?date('H:i:s',strtotime($scan['ultimo_scan'])):'--'?></div></div></section>
<?php if($alertas): ?><section class="card"><h2>Alertas inteligentes</h2><div class="alerts"><?php foreach($alertas as $a): ?><div class="alert <?=h($a['nivel'])?>"><b><?=h($a['titulo'])?></b><span><?=h($a['texto'])?></span></div><?php endforeach; ?></div></section><br><?php endif; ?>
<section class="grid employee-grid">
<?php foreach($funs as $f): $dev=dispositivo_do_funcionario($f['id']); $p=$pres[$hoje.'_'.$f['id']]??null; $isOn=$dev && !empty($dev['ultimo_visto']) && time()-strtotime($dev['ultimo_visto']) <= $tol*60; $st=$p['status']??($isOn?'trabalhando':'offline'); $min=$p['minutos']??0; $extra=$p['extra_minutos']??0; $mes=resumo_funcionario_mes($f['id']); ?>
<div class="card employee"><div class="employee-top"><div class="avatar"><?=mb_strtoupper(mb_substr($f['nome']??'F',0,1))?></div><div><h2><?=h($f['nome'])?></h2><p><?=h($f['cargo']??'Funcionário')?></p></div></div><span class="pill <?=$isOn?'ok':($st==='almoco'?'warn':'off')?>"><?= $isOn?'● Trabalhando':($st==='almoco'?'● Almoço/Pausa':'● Offline') ?></span><div class="mini-grid"><p>Entrada <b><?=!empty($p['entrada'])?date('H:i',strtotime($p['entrada'])):'--:--'?></b></p><p>Saída <b><?=!empty($p['saida'])?date('H:i',strtotime($p['saida'])):'--:--'?></b></p><p>Hoje <b><?=hhmm_from_min($min)?></b></p><p>Extra <b><?=hhmm_from_min($extra)?></b></p><p>Almoço <b><?=hhmm_from_min($p['almoco_minutos']??0)?></b></p><p>Mês <b><?=hhmm_from_min($mes['minutos'])?></b></p></div><p class="muted">Último visto: <?= $dev && !empty($dev['ultimo_visto'])?date('H:i:s',strtotime($dev['ultimo_visto'])):'--' ?></p><p class="muted">Celular: <?= $dev?h(($dev['apelido']?:$dev['mac']).' / '.$dev['ip']):'não vinculado' ?></p><a class="btn ghost" href="funcionario.php?id=<?=urlencode($f['id'])?>">Abrir ficha</a></div>
<?php endforeach; if(!$funs): ?><div class="card"><h2>Nenhum funcionário cadastrado</h2><p>Vá em Configurações e cadastre os funcionários.</p></div><?php endif; ?>
</section>
<?php footer_page(); ?>
